<?php
declare(strict_types=1);requireRole('subject-officer');require_once __DIR__.'/../../config/database.php';$activePage='aid-requests';$errors=[];
try{$rows=database()->query("SELECT ar.*,b.full_name,b.nic,b.date_of_birth,b.address,d.name district_name,ds.name division_name,i.item_name,i.variety,u.full_name sso_name FROM aid_requests ar JOIN beneficiaries b ON b.id=ar.beneficiary_id JOIN districts d ON d.id=b.district_id JOIN ds_divisions ds ON ds.id=b.ds_division_id JOIN inventory_items i ON i.id=ar.item_id JOIN users u ON u.id=ar.submitted_by WHERE ar.status<>'draft' AND u.role='social-service-officer' ORDER BY CASE ar.status WHEN 'pending' THEN 0 WHEN 'approved' THEN 1 WHEN 'rejected' THEN 2 ELSE 3 END,ar.id DESC")->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$rows=[];$errors[]='Aid requests are unavailable.';}
function monitorAge(string $dob):int{return (int)(new DateTimeImmutable($dob))->diff(new DateTimeImmutable('today'))->y;}
?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aid Requests Monitor</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="assets/css/admin-dashboard.css" rel="stylesheet"></head><body><?php require __DIR__.'/../../includes/subject-officer-sidebar.php';?><div class="admin-shell"><header class="topbar"><h1>Aid Requests Monitor</h1></header><main class="dashboard-content"><?php if($errors):?><div class="alert alert-danger"><?=htmlspecialchars(implode(' ',$errors))?></div><?php endif;?><section class="submitted-requests-card"><div class="submitted-header"><div><h2>Requests from Social Service Officers</h2><small>Read-only — only Admin can approve or reject</small></div><div><input id="monitor-search" type="search" placeholder="Search name, NIC or SSO..."><select id="monitor-status"><option value="">All Status</option><option value="pending">Pending Admin</option><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="goods-requested">Goods Requested</option><option value="distributed">Distributed</option></select></div></div><div class="submitted-table-wrap"><table class="submitted-table" id="monitor-table"><thead><tr><th>ID</th><th>Beneficiary</th><th>NIC</th><th>Age</th><th>District / DS</th><th>Aid Requested</th><th>Lens Power</th><th>Approvals</th><th>Submitted By</th><th>Status</th><th>Admin Note</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="11">No submitted aid requests.</td></tr><?php else:foreach($rows as $r):?><tr data-status="<?=htmlspecialchars($r['status'])?>"><td>AR-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></td><td><strong><?=htmlspecialchars($r['full_name'])?></strong><small><?=htmlspecialchars($r['address'])?></small></td><td><?=htmlspecialchars($r['nic']?:'—')?></td><td><?=monitorAge($r['date_of_birth'])?></td><td><?=htmlspecialchars($r['district_name'].' / '.$r['division_name'])?></td><td><?=htmlspecialchars($r['item_name'].($r['variety']?' ('.$r['variety'].')':''))?></td><td><?=$r['prescribed_power']!==null?sprintf('%+.2f',(float)$r['prescribed_power']):'—'?></td><td><?=array_sum([(int)$r['medical_officer_approved'],(int)$r['grama_niladhari_approved'],(int)$r['social_services_approved'],(int)$r['divisional_secretary_approved']])?> / 4</td><td><?=htmlspecialchars($r['sso_name'])?></td><td><span class="request-status-pill status-<?=htmlspecialchars($r['status'])?>"><?=ucwords(str_replace('-',' ',$r['status']))?></span></td><td><?=htmlspecialchars($r['rejection_reason']?:'—')?></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><script src="assets/js/admin-dashboard.js"></script><script>const search=document.getElementById('monitor-search'),status=document.getElementById('monitor-status'),rows=[...document.querySelectorAll('#monitor-table tbody tr[data-status]')];function filterRows(){const term=(search.value||'').toLowerCase(),state=status.value;rows.forEach(row=>row.hidden=!(row.textContent.toLowerCase().includes(term)&&(!state||row.dataset.status===state)))}search.addEventListener('input',filterRows);status.addEventListener('change',filterRows);</script></body></html>
